            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    static void fft(long[] array, int length, int dir) {
        int n = length;
        for (int i = 1, j = 0; i < n; i++) {
